"""Offline rehearsal on SQLite files generated by the plugin, with no host calls."""

import base64
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone
import hashlib
import json
import shutil
from types import SimpleNamespace

import pytest

from astrbot_host.local_config import LocalConfig, LocalConfigServer, MAX_VALUE, Refused, redact
from companion_v2.configuration.models import ConfigLayer, ConfigTarget
from companion_v2.configuration.registry import FieldRegistry
from companion_v2.configuration.service import ConfigurationService
from companion_v2.execution.models import require
from companion_v2.foundation.refs import OperationRef, SubjectKind, SubjectRef, VersionRef
from companion_v2.foundation.outcome import Outcome
from companion_v2.proactive import configuration as contact
from companion_v2.relationships import profile as relationship
from companion_v2.role_profile import configuration as role
from companion_v2.role_work.life import configuration as life
from companion_v2.storage.runtime import StorageRuntime


AT = datetime(2026, 11, 18, tzinfo=timezone.utc)
INSTALLATION = "synthetic"
PERSONALITY = "role.profile.personality"
SPEECH_STYLE = "role.profile.speech_style"
INTERACTION = "relationship.profile.interaction"
CONTACT_INTERVAL = "proactive.contact.interval_seconds"


def build_app(path):
    runtime = StorageRuntime.open(data_root=path, installation_id=INSTALLATION)
    store = StorageRuntime.open_configuration(data_root=path / "configuration", installation_id=INSTALLATION)
    runtime.attach_configuration_store(store)
    owners = (role.RoleProfileConfigurationOwner(runtime), relationship.RelationshipProfileConfigurationOwner(runtime),
              life.LifeConfigurationOwner(runtime), contact.ContactConfigurationOwner(runtime))
    fields = (*role.configuration_fields(), *relationship.configuration_fields(),
              *life.configuration_fields(), *contact.configuration_fields())
    service = ConfigurationService(runtime, FieldRegistry(version="synthetic", fields=fields), store=store, owners=owners)
    app = SimpleNamespace(configuration=service, now=lambda: AT, state="running",
                          tasks=SimpleNamespace(check_generation=lambda: Outcome.success(1)), notify=lambda: None)
    return app, runtime, store


def seed(service, actor, target, name, value, operation_id):
    field = service.registry.fields[name]
    snapshot = require(service.read(actor, target=target, group_id=field.group_id, observed_at=AT))
    return require(service.patch(actor, target=target, group_id=field.group_id,
        operation=OperationRef(operation_id, field.owner_id, target.authorization_scope,
                               VersionRef(operation_id, 1), operation_id),
        expected_edit_token=snapshot.edit_token, changes={name: value}, observed_at=AT))


def edit(adapter, prefix, field, value):
    before = adapter.get(prefix, field)
    return adapter.set(prefix, field, before["revision"], before["edit_token"], value)


@pytest.fixture
def rehearsal(tmp_path):
    source = tmp_path / "synthetic-source"
    app, main, store = build_app(source)
    role_subject = SubjectRef(INSTALLATION, SubjectKind.BOT, "role-a")
    role_target = ConfigTarget(INSTALLATION, ConfigLayer.ROLE, role_subject, bot_id="bot-a")
    relationship_target = ConfigTarget(INSTALLATION, ConfigLayer.RELATIONSHIP, role_subject, bot_id="bot-a",
                                      subject=SubjectRef(INSTALLATION, SubjectKind.HUMAN, "human-a"))
    try:
        service = app.configuration
        actor = LocalConfig(app)._operator(AT)
        seed(service, actor, role_target, PERSONALITY, "沉静", "fixture-role")
        seed(service, actor, relationship_target, INTERACTION, "随和", "fixture-relationship")
    finally:
        store.close()
        main.close()
    copy = tmp_path / "synthetic-rehearsal"
    shutil.copytree(source, copy)
    app, main, store = build_app(copy)
    try:
        yield app, store, role_target, relationship_target
    finally:
        store.close()
        main.close()


def test_change_history_live_reader_and_revert(rehearsal):
    app, store, target, relationship_target = rehearsal
    adapter = LocalConfig(app)
    assert sorted(adapter.targets(), key=lambda item: item["layer"]) == [
        {"target_key": relationship_target.key, "layer": "relationship", "role_id": "role-a", "subject_id": "human-a"},
        {"target_key": target.key, "layer": "role", "role_id": "role-a", "subject_id": None},
    ]
    assert adapter.history(20) == []
    assert adapter.get(target.key[:12], PERSONALITY)["value"] == "沉静"
    change = edit(adapter, target.key[:12], PERSONALITY, "开朗")
    assert change["reload_required"] is False and change["revision"] == 2
    # A reader that already owns its original configuration adapter sees the
    # new value through its ordinary read path after the service transaction.
    owner = role.RoleProfileConfigurationOwner(app.configuration.runtime)
    assert owner.read(target, role.configuration_fields()).fields[PERSONALITY].value == "开朗"
    receipt = store.read_one("SELECT result_json FROM configuration_changes WHERE operation_id = ?",
                             ("companion-config:" + change["change_id"],))
    assert json.loads(receipt["result_json"])["revision"] == 2
    assert store.read_one("SELECT state FROM operations WHERE operation_id = ?",
                          ("companion-config:" + change["change_id"],))["state"] == "completed"
    history, = adapter.history(10)
    assert history["change_id"] == change["change_id"]
    assert not {"old_json", "value"} & set(history)
    adapter.revert(change["change_id"])
    assert adapter.get(target.key, PERSONALITY)["value"] == "沉静"
    assert adapter.history(10)[0]["reverts"] == change["change_id"]
    with pytest.raises(Refused, match="stale_revision"):
        adapter.revert(change["change_id"])

    assert not adapter.get(target.key, SPEECH_STYLE)["explicit"]
    change = edit(adapter, target.key, SPEECH_STYLE, "轻松")
    adapter.revert(change["change_id"])
    assert not adapter.get(target.key, SPEECH_STYLE)["explicit"]
    assert not store.read_one("SELECT 1 FROM configuration_values WHERE target_key=? AND field_id=?",
                              (target.key, SPEECH_STYLE))
    assert edit(adapter, relationship_target.key, INTERACTION, "友善")["revision"] == 2


def test_allowlist_redaction_and_input_schema(rehearsal):
    app, _, target, relationship_target = rehearsal
    adapter = LocalConfig(app)
    for field in ["model.chat.provider", "role.profile.api_token", "role.profile_extra.personality", "wardrobes.x"]:
        with pytest.raises(Refused, match="field_not_allowed"):
            adapter.get(target.key, field)
    with pytest.raises(Refused, match="field_read_only"):
        edit(adapter, relationship_target.key, "relationship.profile.user_birthday", "11-18")
    with pytest.raises(ValueError, match="incorrect type"):
        edit(adapter, target.key, PERSONALITY, True)
    with pytest.raises(Exception, match="no longer"):
        edit(adapter, target.key, PERSONALITY, "甲" * 5000)
    value = "two lines\nauthorization: Bearer offline-fixture-credential"
    change = edit(adapter, target.key, PERSONALITY, value)
    assert adapter.get(target.key, PERSONALITY)["value"] == "[REDACTED]"
    assert "credential" not in json.dumps(adapter.history(20))
    adapter.revert(change["change_id"])
    assert adapter.get(target.key, PERSONALITY)["value"] == "沉静"


@pytest.mark.parametrize("value", [
    'example client_secret=' + ' ' * 90 + 'fixture',
    'example "api-key": "fixture"',
    'https://sample:' + 'x' * 600 + '@example.invalid',
    '-----BEGIN RSA PRIVATE KEY-----',
    'header: Bearer fixture',
])
def test_redacts_entire_secret_like_string(value):
    assert redact(value) == "[REDACTED]"
    assert redact("short synthetic prose") == "short synthetic prose"


def test_compare_and_set_is_atomic_and_revert_refuses_dashboard_change(rehearsal):
    app, store, target, _ = rehearsal
    adapter = LocalConfig(app)

    before = adapter.get(target.key, PERSONALITY)

    def attempt(value):
        try:
            return adapter.set(target.key, PERSONALITY, before["revision"], before["edit_token"], value)
        except Refused as error:
            return str(error)

    with ThreadPoolExecutor(max_workers=2) as executor:
        results = list(executor.map(attempt, ["甲", "乙"]))
    assert results.count("stale_revision") == 1
    change, = [result for result in results if isinstance(result, dict)]
    service = app.configuration
    seed(service, adapter._operator(AT), target, SPEECH_STYLE, "外部保存", "fixture-dashboard")
    with pytest.raises(Refused, match="stale_revision"):
        adapter.revert(change["change_id"])
    assert store.read_one("SELECT COUNT(*) AS n FROM lsr_config_undo", ())["n"] == 1


def request(prefix, field, before, raw, digest=None):
    return json.dumps({"args": ["set", prefix, field, str(before["revision"]), before["edit_token"],
                                digest or hashlib.sha256(raw).hexdigest()],
                       "body": base64.b64encode(raw).decode()}).encode() + b"\n"


@pytest.mark.parametrize("raw,digest,error", [
    (b'"valid"', "0" * 64, "digest_mismatch"),
    (b" " * (MAX_VALUE + 1), None, "value_too_large"),
    (b'"\xff"', None, "invalid_value"),
    (b'"\\ud800"', None, "invalid_value"),
    (b'"truncated', None, "invalid_value"),
    (b"1e999", None, "invalid_value"),
    (b"{}", None, "invalid_value"),
])
def test_wire_rejects_bad_input_before_commit(rehearsal, raw, digest, error):
    app, _, target, _ = rehearsal
    server = LocalConfigServer(SimpleNamespace(session=SimpleNamespace(application=app), _terminated=False))
    before = LocalConfig(app).get(target.key, PERSONALITY)
    assert json.loads(server._dispatch(request(target.key, PERSONALITY, before, raw, digest))) == {
        "ok": False, "error": error}
    assert LocalConfig(app).history(20) == []


def test_wire_writes_through_plugin_and_refuses_unknown_command(rehearsal):
    app, _, target, _ = rehearsal
    seen = []
    app.notify = lambda: seen.append("notified")
    server = LocalConfigServer(SimpleNamespace(session=SimpleNamespace(application=app), _terminated=False))
    before = LocalConfig(app).get(target.key, PERSONALITY)
    response = json.loads(server._dispatch(request(target.key, PERSONALITY, before, b'"kind"')))
    assert response["ok"] and response["result"]["revision"] == 2
    assert seen == ["notified"]
    assert json.loads(server._dispatch(b'{"args":["backup"],"body":null}\n'))["error"] == "invalid_command"


def test_invalid_sleep_timezone_rejected_before_commit(rehearsal):
    app, _, role_target, _ = rehearsal
    adapter = LocalConfig(app)
    field = "role.life.sleep_timezone"
    before = adapter.get(role_target.key, field)
    with pytest.raises(Refused, match="^invalid_configuration_value$"):
        adapter.set(role_target.key, field, before["revision"], before["edit_token"], "Asia/Shangahi")
    assert adapter.get(role_target.key, field) == before
    assert adapter.history(10) == []
    edit(adapter, role_target.key, field, "UTC")
    assert adapter.get(role_target.key, field)["value"] == "UTC"


def test_wire_rejects_stale_inherited_contact_value_at_same_revision(rehearsal):
    app, _, role_target, relationship_target = rehearsal
    adapter = LocalConfig(app)
    server = LocalConfigServer(SimpleNamespace(session=SimpleNamespace(application=app), _terminated=False))
    field = CONTACT_INTERVAL
    before = adapter.get(relationship_target.key, field)
    assert not before["explicit"]
    seed(app.configuration, adapter._operator(AT), role_target, field, 4200, "dashboard-role-contact")
    current = adapter.get(relationship_target.key, field)
    assert current["revision"] == before["revision"]
    assert current["value"] == 4200 != before["value"]
    assert current["edit_token"] != before["edit_token"]
    assert json.loads(server._dispatch(request(relationship_target.key, field, before, b"4800"))) == {
        "ok": False, "error": "stale_revision",
    }
    assert adapter.get(relationship_target.key, field) == current
    assert adapter.history(10) == []
    assert json.loads(server._dispatch(request(relationship_target.key, field, current, b"4800")))["ok"]


def test_contact_writes_are_restricted_to_role_and_relationship(rehearsal):
    app, _, role_target, relationship_target = rehearsal
    adapter = LocalConfig(app)
    installation = ConfigTarget(INSTALLATION, ConfigLayer.INSTALLATION)
    field = CONTACT_INTERVAL
    seed(app.configuration, adapter._operator(AT), installation, field, 4200, "dashboard-installation-contact")
    before = adapter.get(installation.key, field)
    assert before["value"] == 4200 and not before["writable"]
    with pytest.raises(Refused, match="^field_read_only$"):
        adapter.set(installation.key, field, before["revision"], before["edit_token"], 4800)
    assert adapter.get(installation.key, field) == before
    assert adapter.history(10) == []
    for target in (role_target, relationship_target):
        assert adapter.get(target.key, field)["writable"]
        change = edit(adapter, target.key, field, 4800)
        assert change["change_id"] is not None
